// WF8 renders a PDF with no PDF service: this node builds the HTML, the next node
// uploads it to Drive as a Google Doc (Drive converts HTML on the way in), and the
// one after that exports it back as a PDF. See docs/04-workflows.md.
//
// templates/invoice.html and templates/receipt.html in the repo are the readable
// copies of the two strings below — n8n Cloud has no filesystem to read them from.
const BOUNDARY = 'erpboundary';
const FOLDER_ID = 'REPLACE_WITH_DOCUMENTS_FOLDER_ID';

const DOC_TITLE = {
  Invoice: 'חשבונית עסקה',
  TaxInvoice: 'חשבונית מס',
  Receipt: 'קבלה',
  PriceQuote: 'הצעת מחיר',
  Report: 'דוח'
};
const PAYMENT = {
  Cash: 'מזומן',
  CreditCard: 'כרטיס אשראי',
  BankTransfer: 'העברה בנקאית',
  Check: 'צ׳ק',
  Bit: 'ביט'
};

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const nis = (n) => Number(n || 0).toLocaleString('he-IL', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const heDate = (d) => (d ? new Date(d).toLocaleDateString('he-IL') : '—');

// LineItems is a longtext field. Preferred form is a JSON array
// [{name, qty, unitPrice}]; a plain "name x qty @ price" line per row also works.
function lineItemRows(raw) {
  let items = [];
  try {
    const parsed = JSON.parse(raw || '[]');
    if (Array.isArray(parsed)) items = parsed;
  } catch (e) { /* not JSON — fall through */ }

  if (!items.length) {
    items = String(raw || '').split('\n').map((l) => l.trim()).filter(Boolean).map((line) => {
      const m = line.match(/^(.*?)\s*[xX*]\s*(\d+)\s*(?:@\s*([\d.]+))?$/);
      return m ? { name: m[1], qty: Number(m[2]), unitPrice: Number(m[3] || 0) } : { name: line };
    });
  }

  if (!items.length) return '<tr><td colspan="4">—</td></tr>';

  return items.map((it) => {
    const qty = Number(it.qty ?? it.quantity ?? 1);
    const unit = Number(it.unitPrice ?? it.price ?? 0);
    const name = it.name ?? it.description ?? it.Name ?? '';
    return '<tr>'
      + `<td>${esc(name)}</td>`
      + `<td class="num">${qty}</td>`
      + `<td class="num">${nis(unit)} ₪</td>`
      + `<td class="num">${nis(qty * unit)} ₪</td>`
      + '</tr>';
  }).join('\n      ');
}

function invoiceHtml(v) {
  return `<!doctype html>
<html dir="rtl" lang="he">
<head>
  <meta charset="utf-8">
  <title>${esc(v.docTitle)} ${esc(v.docNumber)}</title>
  <style>
    * { box-sizing: border-box; }
    body { font-family: "Arial", "Helvetica", sans-serif; color: #1b2333; margin: 0; padding: 48px; font-size: 14px; }
    .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #1f2d5a; padding-bottom: 16px; }
    .brand h1 { margin: 0; color: #1f2d5a; font-size: 26px; }
    .brand .tagline { color: #6b7280; font-size: 12px; margin-top: 4px; }
    .company { text-align: left; font-size: 12px; color: #4b5563; line-height: 1.6; }
    .doc-meta { margin-top: 24px; display: flex; justify-content: space-between; }
    .doc-meta .box h2 { margin: 0 0 8px; font-size: 18px; color: #1f2d5a; }
    .doc-meta .box p { margin: 2px 0; }
    table { width: 100%; border-collapse: collapse; margin-top: 24px; }
    th { background: #1f2d5a; color: #fff; padding: 10px; text-align: right; font-size: 13px; }
    td { padding: 10px; border-bottom: 1px solid #e5e7eb; }
    tr:nth-child(even) td { background: #f9fafb; }
    .num { text-align: left; direction: ltr; }
    .totals { margin-top: 20px; margin-left: auto; width: 300px; }
    .totals .row { display: flex; justify-content: space-between; padding: 6px 0; }
    .totals .grand { border-top: 2px solid #1f2d5a; margin-top: 6px; padding-top: 10px; font-size: 18px; font-weight: bold; color: #1f2d5a; }
    .footer { margin-top: 48px; text-align: center; color: #9ca3af; font-size: 11px; border-top: 1px solid #e5e7eb; padding-top: 12px; }
  </style>
</head>
<body>
  <div class="header">
    <div class="brand">
      <h1>AI Electronics · איי.איי אלקטרוניקה</h1>
      <div class="tagline">מוצרי אלקטרוניקה מקוריים באחריות יבואן רשמי</div>
    </div>
    <div class="company">
      ח.פ / עוסק מורשה: 515-678-923<br>
      רחוב הברזל 30, תל אביב<br>
      טל' 03-555-1234 · info@aielectronics.co.il
    </div>
  </div>

  <div class="doc-meta">
    <div class="box">
      <h2>${esc(v.docTitle)}</h2>
      <p>מספר מסמך: <strong>${esc(v.docNumber)}</strong></p>
      <p>תאריך: ${esc(v.issueDate)}</p>
      <p>תוקף לתשלום: ${esc(v.dueDate)}</p>
    </div>
    <div class="box">
      <h2>לכבוד</h2>
      <p><strong>${esc(v.customerName)}</strong></p>
      <p>${esc(v.customerBusinessNumber)}</p>
      <p>${esc(v.customerAddress)}</p>
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th>פריט</th>
        <th class="num">כמות</th>
        <th class="num">מחיר יחידה</th>
        <th class="num">סה"כ</th>
      </tr>
    </thead>
    <tbody>
      ${v.lineItemsRows}
    </tbody>
  </table>

  <div class="totals">
    <div class="row"><span>סכום ביניים</span><span class="num">${esc(v.subtotal)} ₪</span></div>
    <div class="row"><span>מע"מ (${esc(v.vatRatePercent)}%)</span><span class="num">${esc(v.vatAmount)} ₪</span></div>
    <div class="row grand"><span>סה"כ לתשלום</span><span class="num">${esc(v.total)} ₪</span></div>
  </div>

  <div class="footer">
    תודה שבחרתם ב-AI Electronics · מסמך זה הופק אוטומטית על ידי מערכת ה-ERP
  </div>
</body>
</html>`;
}

function receiptHtml(v) {
  return `<!doctype html>
<html dir="rtl" lang="he">
<head>
  <meta charset="utf-8">
  <title>קבלה ${esc(v.docNumber)}</title>
  <style>
    body { font-family: "Arial", sans-serif; color: #1b2333; margin: 0; padding: 48px; font-size: 14px; }
    .header { border-bottom: 3px solid #0f766e; padding-bottom: 16px; }
    .header h1 { margin: 0; color: #0f766e; font-size: 26px; }
    .header .company { color: #4b5563; font-size: 12px; margin-top: 6px; line-height: 1.6; }
    .title { margin-top: 28px; font-size: 22px; color: #0f766e; }
    .meta p { margin: 4px 0; }
    .amount { margin-top: 28px; background: #ecfdf5; border: 1px solid #a7f3d0; border-radius: 8px; padding: 20px; text-align: center; }
    .amount .label { color: #047857; font-size: 13px; }
    .amount .value { font-size: 32px; font-weight: bold; color: #0f766e; direction: ltr; }
    .footer { margin-top: 48px; text-align: center; color: #9ca3af; font-size: 11px; border-top: 1px solid #e5e7eb; padding-top: 12px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>AI Electronics · איי.איי אלקטרוניקה</h1>
    <div class="company">ח.פ 515-678-923 · רחוב הברזל 30, תל אביב · טל' 03-555-1234</div>
  </div>

  <div class="title">קבלה מספר ${esc(v.docNumber)}</div>

  <div class="meta">
    <p>תאריך: ${esc(v.issueDate)}</p>
    <p>התקבל מ: <strong>${esc(v.customerName)}</strong></p>
    <p>אמצעי תשלום: ${esc(v.paymentMethod)}</p>
    <p>בגין מסמך: ${esc(v.relatedInvoice)}</p>
  </div>

  <div class="amount">
    <div class="label">סכום ששולם (כולל מע"מ)</div>
    <div class="value">${esc(v.amount)} ₪</div>
  </div>

  <div class="footer">
    קבלה זו מהווה אישור תשלום · הופק אוטומטית על ידי מערכת ה-ERP
  </div>
</body>
</html>`;
}

// ponytail: positional pairing with the Files rows. "Fetch Source Record" has
// alwaysOutputData on, so it emits exactly one item per Files row and the indexes line up.
const files = $('Pending Files').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const file = files[i].json.fields || files[i].json;
  const fileRecordId = files[i].json.id || '';
  const src = $input.all()[i].json.fields || $input.all()[i].json;

  const docType = file.DocType || 'Invoice';
  const docNumber = src.DocNumber ?? file.FileId ?? '';
  const isReceipt = docType === 'Receipt';

  const v = {
    docTitle: DOC_TITLE[docType] || docType,
    docNumber,
    issueDate: heDate(src.IssueDate),
    dueDate: heDate(src.DueDate),
    customerName: src.CustomerName || src.CustomerId || '',
    customerBusinessNumber: src.CustomerBusinessNumber ? `ח.פ / עוסק: ${src.CustomerBusinessNumber}` : '',
    customerAddress: '',
    lineItemsRows: lineItemRows(src.LineItems),
    subtotal: nis(src.Subtotal),
    vatRatePercent: Math.round(Number(src.VATRate || 0) * 100),
    vatAmount: nis(src.VATAmount),
    total: nis(src.Total),
    amount: nis(src.Amount),
    paymentMethod: PAYMENT[src.PaymentMethod] || src.PaymentMethod || '',
    relatedInvoice: src.RelatedInvoice || '—'
  };

  const html = isReceipt ? receiptHtml(v) : invoiceHtml(v);
  const name = `${docType}-${docNumber}`;

  // multipart/related body for Drive's upload endpoint — the JSON part asks for the
  // google-apps.document mimeType, which is what makes Drive convert the HTML.
  const metadata = JSON.stringify({
    name,
    mimeType: 'application/vnd.google-apps.document',
    parents: [FOLDER_ID]
  });

  const multipart = [
    `--${BOUNDARY}`,
    'Content-Type: application/json; charset=UTF-8',
    '',
    metadata,
    `--${BOUNDARY}`,
    'Content-Type: text/html; charset=UTF-8',
    '',
    html,
    `--${BOUNDARY}--`,
    ''
  ].join('\r\n');

  out.push({ json: { fileRecordId, docType, docNumber, name, fileName: `${name}.pdf`, html, multipart } });
}

return out;
